.libPaths(c(file.path((function(x) { if (!nzchar(x)) stop("Set CANINE_CIE_PROJECT_ROOT"); x })(Sys.getenv("CANINE_CIE_PROJECT_ROOT")), "envs", "phase3_r_portable", "library_user"),.libPaths()))
suppressPackageStartupMessages({library(edgeR);library(fgsea);library(data.table)})
R<-(function(x) { if (!nzchar(x)) stop("Set CANINE_CIE_PROJECT_ROOT"); x })(Sys.getenv("CANINE_CIE_PROJECT_ROOT"));O<-file.path(R,"WORKING","24_EPITHELIAL_MYELOID_CROSS_SPECIES");W<-file.path(O,"work")
P<-fread(file.path(W,"predefined_programs.tsv"));M<-fread(file.path(R,"06_pseudobulk","gsea","mapping","phase4_feature_to_geneset_id.csv"));M[,target_geneset_id:=as.character(target_geneset_id)]
ra<-fread(file.path(R,"06_pseudobulk","gsea","gene_sets","reactome_canis_familiaris_gene_sets.tsv.gz"));go<-fread(file.path(R,"06_pseudobulk","gsea","gene_sets","go_bp_canis_familiaris_gene_sets.tsv.gz"));ha<-fread(file.path(R,"06_pseudobulk","gsea","gene_sets","hallmark_dog_ortholog_projected_membership.tsv.gz"))
mem<-unique(rbindlist(list(ra[pathway_id%in%P$dog_pathway_id,.(dog_pathway_id=pathway_id,target_geneset_id=as.character(target_geneset_id))],go[pathway_id%in%P$dog_pathway_id,.(dog_pathway_id=pathway_id,target_geneset_id=as.character(target_geneset_id))],ha[pathway_id%in%P$dog_pathway_id,.(dog_pathway_id=pathway_id,target_geneset_id=as.character(target_geneset_id))])))
sl<-function(x){y<-tolower(strsplit(x,"")[[1]]);y[!grepl("[a-z0-9]",y)]<-"_";gsub("^_+|_+$","",paste0(y,collapse=""))}
run<-function(lin,st,omit="NONE",off=0L){
 c<-fread(file.path(W,paste0("counts_",tolower(lin),"_",sl(st),".tsv")));m<-fread(file.path(W,paste0("samples_",tolower(lin),"_",sl(st),".tsv")));if(omit!="NONE")m<-m[donor_id!=omit];nh<-m[condition=="Healthy",uniqueN(donor_id)];nc<-m[condition=="CIE",uniqueN(donor_id)];if(nh<3||nc<3)return(list(ok=FALSE,why="NON_ESTIMABLE_DONOR_GATE",nh=nh,nc=nc))
 ids<-m$sample_id;a<-c[,.(feature_id,gene_symbol)];x<-as.matrix(c[,..ids]);storage.mode(x)<-"integer";rownames(x)<-a$feature_id;m[,condition:=factor(condition,levels=c("Healthy","CIE"))];d<-model.matrix(~condition,m);y<-DGEList(x,genes=a);k<-filterByExpr(y,design=d);y<-y[k,,keep.lib.sizes=FALSE];y<-calcNormFactors(y);y<-estimateDisp(y,d,robust=TRUE);f<-glmQLFit(y,d,robust=TRUE);q<-glmQLFTest(f,coef="conditionCIE");t<-as.data.table(topTags(q,n=Inf,sort.by="none")$table);t[,rank:=sign(logFC)*sqrt(F)]
 z<-merge(t,M[,.(feature_id,target_geneset_id)],by="feature_id");z<-z[is.finite(rank)&!is.na(target_geneset_id)&nzchar(target_geneset_id)];z[,ar:=abs(rank)];setorder(z,target_geneset_id,-ar,PValue,feature_id);z<-z[,.SD[1],by=target_geneset_id];s<-z$rank;names(s)<-z$target_geneset_id;pp<-P[lineage==lin];paths<-split(mem[dog_pathway_id%in%pp$dog_pathway_id,target_geneset_id],mem[dog_pathway_id%in%pp$dog_pathway_id,dog_pathway_id]);set.seed(20261016+off);g<-as.data.table(fgseaMultilevel(paths,s,minSize=15,maxSize=500,eps=1e-10,nproc=1));setnames(g,"pathway","dog_pathway_id");if(nrow(g)){g[,leading_edge_n:=lengths(leadingEdge)];g[,leadingEdge:=NULL]}else{g<-data.table(dog_pathway_id=character(),ES=numeric(),NES=numeric(),pval=numeric(),size=integer(),leading_edge_n=integer())};u<-merge(pp,g[,.(dog_pathway_id,ES,NES,pval,size,leading_edge_n)],by="dog_pathway_id",all.x=TRUE)
 u[,c("subtype","omitted_donor","healthy_donors","cie_donors","tested_genes","mapped_ranked_genes","model_status","direction"):=list(st,omit,nh,nc,sum(k),nrow(z),ifelse(is.na(NES),"PATHWAY_NOT_TESTABLE","ESTIMABLE"),ifelse(is.na(NES),"NOT_ASSESSABLE",ifelse(NES>0,"CIE_HIGHER","CIE_LOWER")))];list(ok=TRUE,x=u)}
E<-fread(file.path(W,"canine_eligibility_for_r.tsv"));F<-list();L<-list()
for(i in seq_len(nrow(E))){lin<-E$lineage[i];st<-E$subtype[i];a<-tryCatch(run(lin,st,"NONE",i*100),error=function(e)list(ok=FALSE,why=paste0("MODEL_ERROR:",conditionMessage(e)),nh=NA,nc=NA));if(a$ok)x<-a$x else{x<-copy(P[lineage==lin]);x[,c("subtype","omitted_donor","healthy_donors","cie_donors","ES","NES","pval","size","leading_edge_n","tested_genes","mapped_ranked_genes","model_status","direction"):=list(st,"NONE",a$nh,a$nc,NA,NA,NA,NA,NA,NA,NA,a$why,"NOT_ASSESSABLE")]};F[[length(F)+1]]<-x;m<-fread(file.path(W,paste0("samples_",tolower(lin),"_",sl(st),".tsv")))
 for(j in seq_len(nrow(m))){dd<-m$donor_id[j];b<-tryCatch(run(lin,st,dd,i*100+j),error=function(e)list(ok=FALSE,why=paste0("MODEL_ERROR:",conditionMessage(e)),nh=NA,nc=NA));if(b$ok)y<-b$x else{y<-copy(P[lineage==lin]);y[,c("subtype","omitted_donor","healthy_donors","cie_donors","ES","NES","pval","size","leading_edge_n","tested_genes","mapped_ranked_genes","model_status","direction"):=list(st,dd,b$nh,b$nc,NA,NA,NA,NA,NA,NA,NA,b$why,"NOT_ESTIMABLE")]};y[,omitted_condition:=m[donor_id==dd,condition][1]];L[[length(L)+1]]<-y}}
F<-rbindlist(F,fill=TRUE);F[,BH_q:=p.adjust(pval),by=lineage];F[,planned_family:=ifelse(lineage=="Epithelial","12 planned tests","3 planned tests")];L<-rbindlist(L,fill=TRUE);L<-merge(L,F[,.(lineage,subtype,frozen_program_id,full_NES=NES)],by=c("lineage","subtype","frozen_program_id"),all.x=TRUE);L[,direction_match_full:=fifelse(is.na(NES),"NOT_ESTIMABLE",fifelse(sign(NES)==sign(full_NES),"YES","NO"))]
fwrite(F,file.path(W,"phase7_native_program_results.tsv"),sep="\t",na="");fwrite(L,file.path(W,"phase7_native_program_lodo.tsv"),sep="\t",na="");cat("DONE rows=",nrow(F)," lodo=",nrow(L)," valid=",sum(!is.na(F$pval)),"\n",sep="")